def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Final round: defect is dominant when there is no future consequence.
    if n >= 99:
        return 'D'

    # Establish a baseline of early cooperation.
    if n <= 2:
        return 'C'

    last_my, last_opp = history[-1]

    opp_def = 0
    recent5_opp_def = 0
    recent5_my_def = 0
    recent10_opp_def = 0
    coop_after_my_D = 0

    for i in range(n):
        my, opp = history[i]

        if opp == 'D':
            opp_def += 1
            if i >= n - 5:
                recent5_opp_def += 1
            if i >= n - 10:
                recent10_opp_def += 1

        if my == 'D' and i >= n - 5:
            recent5_my_def += 1

        # Opponent cooperated in the next round after we defected.
        if i > 0:
            prev_my, _ = history[i - 1]
            if prev_my == 'D' and opp == 'C':
                coop_after_my_D += 1

    # Current streak of opponent defections at the end of history.
    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak += 1
        else:
            break

    rate = opp_def / float(n)
    forgive_limit = max(1, n // 10)

    if last_opp == 'D':
        if last_my == 'C':
            # Break punishment loops:
            # previous round was (D, C), current opponent D after our C.
            if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C':
                return 'C'

            # Short-window hostility is not forgiven merely because global count is low.
            if recent5_opp_def >= 3 and rate > 0.1:
                return 'D'

            # Treat rare defections from otherwise nice opponents as mistakes.
            if opp_def <= forgive_limit:
                return 'C'
            if rate < 0.15 and opp_streak <= 2:
                return 'C'

            # Retaliate once.
            return 'D'

        # Mutual defection last round.
        # Stay hard against clearly hostile / persistent defectors.
        if rate > 0.45 or opp_streak > 5:
            return 'D'
        if recent10_opp_def >= 8:
            return 'D'

        # If evidence suggests a non-retaliatory or periodic exploiter, keep pressure.
        if coop_after_my_D >= 3 and opp_streak <= 2 and recent5_opp_def <= 3:
            return 'D'
        if opp_streak <= 2 and recent5_my_def >= 2 and rate < 0.30:
            return 'D'

        # Otherwise, attempt to re-establish cooperation.
        return 'C'

    # Opponent cooperated last round.
    if last_my == 'D':
        # They allowed a unilateral defection. Exploit if they appear forgiving,
        # but avoid endless cycles against retaliators.
        if rate < 0.30 and (coop_after_my_D >= 2 or recent5_opp_def <= 3):
            return 'D'
        if coop_after_my_D >= 3 and recent5_opp_def <= 2 and rate < 0.45:
            return 'D'
        return 'C'

    # Mutual cooperation: default to cooperation, except for the forced final-round D above.
    return 'C'
